import React, { useState } from "react";
import axios from "axios";
import { useNavigate } from "react-router-dom";
import { fetchVideoMetadata, downloadAndUploadVideo } from "../axios-use/api";
import "./clipper.css";

function Clipper() {
    const [videoURL, setVideoURL] = useState("");
    const [videoData, setVideoData] = useState(null);
    const [loading, setLoading] = useState(false);
    const [processing, setProcessing] = useState(false); // New state for processing
    const [error, setError] = useState(null);
    const [optimizationType, setOptimizationType] = useState("");
    const [aspectRatio, setAspectRatio] = useState("16:9");
    const [clipLength, setClipLength] = useState("90s");
    const [clipCount, setClipCount] = useState(1);

    const navigate = useNavigate();

    const handleFetch = async () => {
        setLoading(true);
        setError(null);
        setVideoData(null);

        if (!videoURL.trim()) {
            setError("Please enter a valid YouTube URL.");
            setLoading(false);
            return;
        }

        try {
            const data = await fetchVideoMetadata(videoURL);
            setVideoData(data);
            const downloadResponse = await downloadAndUploadVideo(videoURL);
            console.log("Video download and upload response:", downloadResponse);
        } catch (err) {
            setError(err.response?.data?.error || "Error fetching video. Please try again.");
            console.error("Error during fetch:", err);
        } finally {
            setLoading(false);
        }
    };

    const handleOptimizationTypeChange = (type) => {
        setOptimizationType(type);
        setAspectRatio(type === "Long Form" ? "16:9" : "9:16");
    };

    const handleGenerateClick = async () => {
        if (!videoData) {
            alert("Please fetch video data before generating.");
            return;
        }

        const payload = {
            videoURL,
            optimizationType,
            aspectRatio,
            clipLength,
            clipCount,
        };

        setProcessing(true);

        try {
            console.log("Payload:", payload);
            const csrfToken = document.cookie
                .split("; ")
                .find((row) => row.startsWith("csrftoken"))
                ?.split("=")[1];

            const response = await axios.post(
                "http://127.0.0.1:8000/api/process_short_form_video/",
                payload,
                {
                    headers: {
                        "X-CSRFToken": csrfToken,
                        "Content-Type": "application/json",
                    },
                }
            );

            if (response.data.clips) {
                navigate("/clippreview", {
                    state: {
                        videoUrl: videoURL,
                        videoThumbnail: videoData.thumbnail,
                        clips: response.data.clips,
                    },
                });
            } else {
                alert("No clips generated.");
            }
        } catch (err) {
            console.error("Error generating video:", err);
            alert(err.response?.data?.error || "Error during video generation. Please try again.");
        } finally {
            setProcessing(false);
        }
    };

    return (
        <div className="clipper-container">
            {/* Your existing UI */}
            <div className="generate-btn">
                <button
                    onClick={handleGenerateClick}
                    disabled={!optimizationType || !videoData || processing}
                >
                    {processing ? "Processing..." : "Generate"}
                </button>
            </div>
        </div>
    );
}

export default Clipper;
